def components(y0,y1):
    seen=[[False]*w for _ in range(y1-y0)]
    comps=[]
    for y in range(y0,y1):
        for x in range(w):
            if seen[y-y0][x] or is_bg(get(x,y)): continue
            stack=[(x,y)]; seen[y-y0][x]=True
            minx=maxx=x; miny=maxy=y; n=0
            while stack:
                cx,cy=stack.pop(); n+=1
                minx=min(minx,cx); maxx=max(maxx,cx); miny=min(miny,cy); maxy=max(maxy,cy)
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
