#include "theme.hpp"

#include <QApplication>
#include <QFont>
#include <QPalette>
#include <QStyleFactory>

namespace weaknet {
namespace dashboard {

namespace {

/**
 * @brief 构建全局 QSS
 *
 * 结构按「容器 → 文本 → 控件」分层，与 Qt 官方的层叠顺序一致：
 * 同等特异性下后写的规则覆盖先写的，因此交互态（`:hover` / `:pressed`）
 * 必须写在基础规则之后。
