import zlib, struct
def load_png(path):
    f=open(path,'rb').read(); pos=8; idat=b''; w=h=None
    while pos<len(f):
        ln=struct.unpack('>I',f[pos:pos+4])[0]; typ=f[pos+4:pos+8]; data=f[pos+8:pos+8+ln]
        if typ==b'IHDR': w,h,bd,ct=struct.unpack('>IIBB',data[:10])
        elif typ==b'IDAT': idat+=data
        pos+=12+ln
    raw=zlib.decompress(idat); bpp=3; stride=w*bpp
    out=bytearray(h*stride); prev=bytearray(stride); p=0
    for y in range(h):
        ft=raw[p]; p+=1; line=bytearray(raw[p:p+stride]); p+=stride
        if ft==1:
            for i in range(bpp,stride): line[i]=(line[i]+line[i-bpp])&0xFF
        elif ft==2:
            for i in range(stride): line[i]=(line[i]+prev[i])&0xFF
        elif ft==3:
            for i in range(stride):
                a=line[i-bpp] if i>=bpp else 0
                line[i]=(line[i]+((a+prev[i])>>1))&0xFF
        elif ft==4:
            for i in range(stride):
                a=line[i-bpp] if i>=bpp else 0; b=prev[i]; c=prev[i-bpp] if i>=bpp else 0
                pa,pb,pc=abs(b-c),abs(a-c),abs(a+b-2*c)
                pr=a if (pa<=pb and pa<=pc) else (b if pb<=pc else c)
                line[i]=(line[i]+pr)&0xFF
        out[y*stride:(y+1)*stride]=line; prev=line
    return w,h,out
