    const bool rssiStale = stale(rssi_sample_ts);
    const bool jitterStale = stale(jitter_sample_ts);
    const bool tcpLossStale = stale(tcp_loss_sample_ts);
    const bool trafficStale = stale(traffic_sample_ts);

