    // 一旦开了 setter，这个约束就没有守卫了。
    // -----------------------------------------------------------------------

    /// 当前绘制的指标
    HistoryMetric current_metric() const { return current_metric_; }

    /// 当前查询的时间窗
    HistoryWindow current_window() const { return current_window_; }

private slots:
    void onExperienceReady(const QByteArray& json);
    void onDiagnosisReady(const QByteArray& json);
    void onHistoryReady(const QByteArray& json);
    void onFetchFailed(const QString& stage, const QString& error);
    void onRefreshFinished();
    void onRefreshClicked();

    /// 指标选择器变更（白名单第 1 项）
    ///
    /// **只换视图，不重置时间窗**：用户先选「13 小时」再切到 RSSI，
    /// 期望看的仍然是 13 小时的 RSSI。
    void onMetricSelected(int index);

    /// 时间窗按钮点击（白名单第 2 项）
    ///
    /// **只换取数范围，不重置指标**，理由同上。
    void onWindowSelected(int window_id);

    /// 导出当前画面为 PNG（白名单第 3 项）
    void onExportClicked();

private:
    void build_ui();
    /// 顶栏右侧的展示态控制区（指标选择器 + 时间窗按钮 + 导出）
    void build_view_controls(QHBoxLayout* top);
    void apply_experience(const ExperienceSnapshot& snap);
    void apply_diagnosis(const DiagnosisSnapshot& snap);
    void update_status_label(const SleItem& item, QLabel* state_label,
                             QLabel* dot_label);
    static QString state_color(const QString& state);

    /// 重算图标题（网卡 + 指标 + 窗口），并把它交给 LineChartWidget
    void refresh_chart_title();

    /// 把当前画面存成 PNG，返回实际写入路径（失败为空）
    QString export_screenshot();

    DataFetchThread* fetcher_ = nullptr;
    LineChartWidget* chart_ = nullptr;

    /// 历史查询使用的网卡（空表示全部）。
    ///
    /// 这是**请求侧**的事实，不能从 `HistorySeries` 推断：
    /// 查询全部网卡时，任意一条记录的 iface 都不代表整个序列。
    /// 折线图标题直接用它，避免出现「标题写着 wlan0，实际混了 eth0」。
    QString interface_;

    // 顶栏
    QPushButton* refresh_button_ = nullptr;
    QLabel* iface_label_ = nullptr;
    QLabel* score_label_ = nullptr;
    QLabel* timestamp_label_ = nullptr;

    // -----------------------------------------------------------------------
    // 展示态控制（现场交互终端白名单的落地点）
    //
    // 产品定位 v1.2 允许现场改的只有「展示态」：看哪个指标、看多长时间、
    // 把当前画面导出。这三个控件就是那三项，**一个不多**。
    //
    // 绝对不在这里加的东西（违反白名单会直接越过权责契约）：
    //   - 触发 pending_actions / 执行动作
    //   - 改阈值、改配置
    //   - 重启服务、重连
    //   - 任何“就地算一个结论”的按钮
    //
    // 新增交互点前先读 `docs/产品定位-工业无线诊断网关.md` 第三节之二。
    // -----------------------------------------------------------------------

    /// 趋势指标选择器（白名单第 1 项）
    QComboBox* metric_combo_ = nullptr;

    /// 时间窗按钮（白名单第 2 项）：1h / 6h / 24h，互斥
    QPushButton* window_1h_button_ = nullptr;
    QPushButton* window_6h_button_ = nullptr;
    QPushButton* window_24h_button_ = nullptr;

    /// 截图导出（白名单第 3 项）
    QPushButton* export_button_ = nullptr;

    /// 当前展示的指标与时间窗。切换时二者互不干扰：
    /// 换窗口不能把指标重置，换指标也不能把窗口重置。
    HistoryMetric current_metric_ = HistoryMetric::Score;
    HistoryWindow current_window_ = HistoryWindow::Last1h;

    /// 各维度状态汇总「● 3 ● 2 ● 1 ○ 7」（count_by_state 的消费者）
    QLabel* summary_label_ = nullptr;
    /// 评估档位与覆盖度（assessment_profile 的消费者）
    QLabel* profile_label_ = nullptr;

    // 维度状态标签（顺序与 dashboard_data.hpp 中字段一致）
    QLabel* ip_reachability_label_ = nullptr;
    QLabel* responsiveness_label_ = nullptr;
    QLabel* reliability_label_ = nullptr;
    QLabel* rf_health_label_ = nullptr;

    QLabel* dns_label_ = nullptr;
    QLabel* tcp_connect_label_ = nullptr;
    QLabel* tcp_rtt_label_ = nullptr;
    QLabel* http_access_label_ = nullptr;
    QLabel* captive_portal_label_ = nullptr;
    QLabel* active_dns_label_ = nullptr;
    QLabel* active_tcp_label_ = nullptr;
    QLabel* active_https_label_ = nullptr;
    QLabel* active_portal_label_ = nullptr;

    // 每个维度左侧的状态圆点。
    //
    // 圆点与状态文本分别持有指针：`update_status_label()` 要在一次调用里
    // 同时给两者上色。改进前圆点由 `make_status_row()` 创建后就没再被引用，
    // 永远保持默认前景色，14 行扫下来看不出哪几项异常。
    QLabel* ip_reachability_dot_ = nullptr;
    QLabel* responsiveness_dot_ = nullptr;
    QLabel* reliability_dot_ = nullptr;
    QLabel* rf_health_dot_ = nullptr;

    QLabel* dns_dot_ = nullptr;
    QLabel* tcp_connect_dot_ = nullptr;
    QLabel* tcp_rtt_dot_ = nullptr;
    QLabel* http_access_dot_ = nullptr;
    QLabel* captive_portal_dot_ = nullptr;
    QLabel* active_dns_dot_ = nullptr;
    QLabel* active_tcp_dot_ = nullptr;
    QLabel* active_https_dot_ = nullptr;
    QLabel* active_portal_dot_ = nullptr;

    // 底栏
    //
    // experience 与 diagnosis 是**两个独立的异步数据源**，返回时序不定
    // （DataFetchThread 先发 experienceReady 再发 diagnosisReady，但二者
    // 都是队列连接，实际到达顺序不保证）。因此它们各自拥有独立控件：
    // 共用一个 QLabel 会让后到者覆盖先到者的内容。
    /// 体验快照的结论行：等待评估原因 / 首要问题（experience 独占）
    QLabel* experience_label_ = nullptr;
    /// 体验快照的警告（experience 独占，无警告时隐藏）
    QLabel* experience_detail_label_ = nullptr;
    /// 诊断结论行：故障域 + 置信度 + 动作数（diagnosis 独占）
    QLabel* diagnosis_label_ = nullptr;
    /// 诊断的人读摘要（diagnosis 独占，default_summary_template 的消费者）
    QLabel* summary_template_label_ = nullptr;
    /// 次要问题 / 已排除原因 / 证据（diagnosis 独占，可折叠）
    QLabel* diagnosis_extra_label_ = nullptr;
    QLabel* status_bar_label_ = nullptr;

    /// 本轮刷新是否出现过失败。
    ///
    /// 不能用「状态栏文字是否以『取数失败』开头」判断：那是跨轮持久的状态，
    /// 一旦出现过失败，之后即使每轮都成功也永远不会复位回「就绪」。
    /// 这里按轮记录，onRefreshFinished 时消费并清空。
    bool round_had_failure_ = false;

    bool refresh_in_flight_ = false;
};

} // namespace dashboard
} // namespace weaknet

#endif // WEAKNET_QT_DASHBOARD_MAIN_WINDOW_HPP

/**
 * @file data_source.hpp
 * @brief 取数层：调用 libweaknet 的 C API 拿原始 JSON
 *
 * ## 为什么单独一层
 *
 * 数据层（`parse_xxx`）只做 JSON → POD 的纯转换，它不知道数据从哪来。
 * 取数层负责「去拿 JSON」这件事，是唯一直接调用 `weaknet_*` 的地方。
 * 解析由调用方（主线程槽函数）调 `parse_xxx()` 完成，本层不解析。
 *
 * 分开的好处：数据层可以在没有 D-Bus、没有服务端的机器上单测；
 * 取数层可以在板端用真实服务验证。
 *
 * ## 为什么必须后台线程
 *
 * `weaknet_get_*` 内部走 D-Bus 同步调用（`dbus_connection_send_with_reply_and_block`），
 * 在服务端忙或 D-Bus 卡住时会阻塞数秒。如果在 Qt 主线程调用，界面会冻结。
 *
 * ## 缓冲区策略
 *
 * C API 的签名是 `(buffer, buffer_size, error_buffer, error_size)`，
 * 返回值只表示调用成败，不告诉你需要多大缓冲区。看板的 JSON 可能较大
 * （schema v2 快照含 13 个维度 + evidence，历史 100 条），因此采用
 * **先试小缓冲区、遇到疑似截断就扩大重试**的策略。
 *
 * 注意：C API 没有明确的「缓冲区不足」错误码，截断时可能返回 true 但
 * JSON 不完整。因此这里用 `JsonReader::valid()` 判断完整性，不合法就翻倍重试。
 */

#ifndef WEAKNET_QT_DASHBOARD_DATA_SOURCE_HPP
#define WEAKNET_QT_DASHBOARD_DATA_SOURCE_HPP

#include <cstddef>
#include <string>

namespace weaknet {
namespace dashboard {

/**
 * @brief 一次取数操作的结果
 *
 * 把「成功/失败」和「失败原因」显式分开，避免调用方拿着空字符串猜。
 */
struct FetchResult {
    /// C API 是否返回成功
    bool ok = false;

    /// 失败原因（ok 为 true 时为空）
    std::string error;

    /// 原始 JSON（调试用；失败时可能为空或被截断）
    std::string json;
};

/**
 * @brief 取数层
 *
 * 所有方法都是**阻塞**的，必须在后台线程调用，不要放在 UI 线程。
 */
class DataSource {
public:
    DataSource();
    ~DataSource();

    // 禁止拷贝：内部持有 weaknet_init/cleanup 的配对状态
    DataSource(const DataSource&) = delete;
    DataSource& operator=(const DataSource&) = delete;

    /**
     * @brief 初始化 libweaknet 并建立 D-Bus 连接
     *
     * 幂等：已成功初始化后重复调用直接返回 true。
     *
     * **失败后可重试**：失败路径内部会调用 `weaknet_cleanup()` 把库的全局
     * 客户端置空，因此可以隔一段时间再次调用 `init()` 真正重连，而不是
     * 永远停留在同一个失败结果上。板端开机早期 D-Bus 尚未就绪时依赖这一点。
     *
     * @return true 成功；false 失败（可用 last_error() 取原因）
     */
    bool init();

    /**
     * @brief 释放 D-Bus 连接
     *
     * 析构时自动调用。
     */
    void cleanup();

    /// 最近一次 init() 失败的原因
    const std::string& last_error() const { return last_error_; }

    // -----------------------------------------------------------------------
    // 取数接口（全部阻塞）
    // -----------------------------------------------------------------------

    /**
     * @brief 取网络体验快照（schema v2）
     *
     * 对应 D-Bus `GetNetworkExperience`。
     * 服务端在无快照时也会返回合法的 UNKNOWN JSON，调用方用
     * `parse_experience()` + `available()` 判断，不在这里解析。
     */
    FetchResult fetch_experience_raw() const;

    /**
     * @brief 取诊断事实
     */
    FetchResult fetch_diagnosis_raw() const;

    /**
     * @brief 取历史趋势
     *
     * @param interface 网卡名；空字符串表示全部
     * @param limit     最多返回条数（服务端上限 10000，且 <=0 会被钳制为 1）
     * @param start     起始时间（含），格式与 `ts` 列一致 `%Y-%m-%dT%H:%M:%S`；
     *                  空串表示不限
     * @param end       结束时间（含），同上
     *
     * ## start/end 的真实语义
     *
     * `server/src/database_manager.cpp` 的 `queryHistory()` 把它们拼成
     * `ts >= ?` / `ts <= ?`，**不是**降采样、不是聚合。因此
     * 「取最近 6 小时」= 算出一个 start 时间串 + 给一个足够大的 limit。
     *
     * ## limit 与时间窗必须同时给足，缺一不可
     *
     * 服务端是 `ORDER BY ts DESC LIMIT ?`——先按时间倒序，再截断。
     * 若 start 给 24 小时前、limit 只给 1440，返回的是
     * **最新 1440 条**（采样间隔 10 秒 → 只有 4 小时），
     * 标签写着 24h、图里只有 4h。这是数据保真度上的谎报，比多花几 MB 内存坏得多。
     *
     * 所以 limit 必须按 `窗口秒数 / 采样间隔` 算足：
     *
     * | 窗口 | 采样间隔 | 需要的点 | 预估字节 | 服务端上限 10000 |
     * | --- | --- | --- | --- | --- |
     * | 1h  | 10s | 360  | 0.27 MB | 够 |
     * | 6h  | 10s | 2160 | 1.61 MB | 够 |
     * | 24h | 10s | 8640 | 6.46 MB | 够 |
     *
     * 7 天需要 60480 点，**超过服务端 10000 上限**，因此界面不提供 7d。
     * 这不是「懒得做」，而是当前服务端能力边界——加上去只会得到一份
     * 被静默截断的假数据。
     *
     * 缓冲区的 `kMaxBuffer` 已按 24h 的真实体积上调（见 data_source.cpp）。
     */
    FetchResult fetch_history_raw(const std::string& interface, int limit,
                                  const std::string& start = std::string(),
                                  const std::string& end = std::string()) const;

private:
    /**
     * @brief 通用取数模板：调用 C API 并按需扩大缓冲区
     *
     * @param caller 形如 `[](char* b, size_t n, char* e, size_t en) { return weaknet_xxx(b, n, e, en); }`
     */
    template <typename Caller>
    FetchResult invoke(Caller caller) const;

    bool initialized_ = false;
    std::string last_error_;
};

} // namespace dashboard
} // namespace weaknet

#endif // WEAKNET_QT_DASHBOARD_DATA_SOURCE_HPP

/**
 * @file data_source.cpp
 * @brief DataSource 实现
 */

#include "data_source.hpp"

#include <cstring>
#include <vector>

#include "json_reader.hpp"
#include "weaknet_client.h"

namespace weaknet {
namespace dashboard {

namespace {

/// 初始缓冲区大小。schema v2 快照典型 3-8 KB，先给 8 KB。
constexpr size_t kInitialBuffer = 8 * 1024;

/**
 * @brief 缓冲区上限
 *
 * 由 4 MB 上调到 12 MB。原因不是"多给点总没错"，而是有一个具体的
 * 真实需求装不下：
 *
 *   24 小时窗口 × 采样间隔 10 秒 = 8640 个点
 *   真机实测每行 JSON 约 784 字节（kBoardRealHistory 的字段形状）
 *   → 8640 × 784 ≈ 6.46 MB，超过原上限 4 MB。
 *
 * 超过上限时的行为是**报错**（不是静默截断），所以原有代码不会给出假数据；
 * 代价是 24h 窗口永远失败。既然时间窗切换是白名单批准的现场功能，
 * 就得让它真能工作。
 *
 * 取 12 MB 而不是刚好 6.5 MB：留出约 2 倍余量，因为
 *   - 每行含 iface / rssi_source / score_model 等字符串字段，长度可变
 *   - 全部网卡查询（interface 为空）时行数不变但字段可能更长
 *   - assessment_profile 从 UNSPECIFIED 变成 INTERNET_ACCESS 会让每行长几字节
 *
 * 内存代价：这块缓冲只存在于取数线程的栈外堆上，且只在一次调用期间存在，
 * 板端（1GB+ 内存）完全承受得起。相比之下，静默少画 20 小时更不可接受。
 */
constexpr size_t kMaxBuffer = 12 * 1024 * 1024;

/// 错误信息缓冲区大小
constexpr size_t kErrorBufferSize = 512;

} // namespace

DataSource::DataSource() = default;

DataSource::~DataSource() {
    cleanup();
}

bool DataSource::init() {
    if (initialized_) {
        return true;
    }
    last_error_.clear();
    if (!weaknet_init()) {
        // 必须 cleanup，否则本层将永久卡死在失败状态。
        //
        // weaknet_init() 在 client.cpp:1348 的实现是：g_client 非空时直接
        // return g_client->isConnected()，而 connected_ 只在 initConnection()
        // 里赋值一次。连接失败后 g_client 仍留在全局，于是后续每次
        // weaknet_init() 都走 "already initialized" 分支、永远返回 false。
        //
        // weaknet_cleanup() 把 g_client 置空并 disconnect，下一次 init() 才会
        // 真正重建连接。副作用是它会调用 Logger::shutdown()，下次 init 再
        // InitGoogleLogging()——已实测 Init/Shutdown 反复循环安全。
        weaknet_cleanup();
        last_error_ = "weaknet_init() failed: cannot establish D-Bus connection";
        return false;
    }
    initialized_ = true;
    return true;
}

void DataSource::cleanup() {
    if (initialized_) {
        // weaknet_cleanup() 释放内部 D-Bus 连接。
        // 多次调用是安全的，但这里仍用标志位确保配对。
        weaknet_cleanup();
        initialized_ = false;
    }
}

// ---------------------------------------------------------------------------
// 通用取数模板
// ---------------------------------------------------------------------------

template <typename Caller>
FetchResult DataSource::invoke(Caller caller) const {
    FetchResult result;

    if (!initialized_) {
        result.error = "DataSource not initialized; call init() first";
        return result;
    }

    std::vector<char> buffer(kInitialBuffer, '\0');
    std::vector<char> error(kErrorBufferSize, '\0');

    while (true) {
        // 每轮重置，避免上一轮的残留内容干扰判断
        std::fill(buffer.begin(), buffer.end(), '\0');
        std::fill(error.begin(), error.end(), '\0');

        const bool ok = caller(buffer.data(), buffer.size(),
                               error.data(), error.size());

        // error 缓冲区非空表示服务端或库层报了明确错误
        const std::string error_text(error.data());

        if (!ok) {
            result.error = error_text.empty()
                               ? "C API returned false without error message"
                               : error_text;
            result.json.assign(buffer.data());
            return result;
        }

        // 成功时要确认内容完整：C API 不报告截断，只能自己判断。
        // 判定标准：非空，且 JsonReader 认为结构闭合。
        std::string candidate(buffer.data());

        if (candidate.empty()) {
            result.error = "C API returned true but buffer is empty";
            return result;
        }

        // 内容长度接近缓冲区上限 → 极可能被截断，扩大重试
        const bool near_full = candidate.size() + 1 >= buffer.size();
        JsonReader reader(candidate);
        const bool complete = reader.valid();

        if (complete && !near_full) {
            result.ok = true;
            result.json = std::move(candidate);
            return result;
        }

        if (buffer.size() >= kMaxBuffer) {
            // 已达上限仍不完整：如实报告，不假装成功
            result.error = "response exceeds max buffer (" +
                           std::to_string(kMaxBuffer) + " bytes) or is malformed";
            result.json = std::move(candidate);
            return result;
        }

        buffer.resize(buffer.size() * 2);
    }
}

// ---------------------------------------------------------------------------
// 具体接口
// ---------------------------------------------------------------------------

FetchResult DataSource::fetch_experience_raw() const {
    return invoke([](char* b, size_t n, char* e, size_t en) {
        return weaknet_get_network_experience(b, n, e, en);
    });
}

FetchResult DataSource::fetch_diagnosis_raw() const {
    return invoke([](char* b, size_t n, char* e, size_t en) {
        return weaknet_get_diagnosis(b, n, e, en);
    });
}

FetchResult DataSource::fetch_history_raw(const std::string& interface,
                                          int limit,
                                          const std::string& start,
                                          const std::string& end) const {
    return invoke([&interface, limit, &start, &end](char* b, size_t n, char* e,
                                                    size_t en) {
        // start / end 传空串表示不限时间范围
        return weaknet_get_history(interface.c_str(), start.c_str(), end.c_str(),
                                   limit, b, n, e, en);
    });
}

} // namespace dashboard
} // namespace weaknet

