/**
 * @file data_source.cpp
 * @brief DataSource 实现
 */

#include "data_source.hpp"

#include <cstring>
#include <vector>

#include "json_reader.hpp"
#include "weaknet_client.h"

namespace weaknet {
namespace dashboard {

namespace {

/// 初始缓冲区大小。schema v2 快照典型 3-8 KB，先给 8 KB。
constexpr size_t kInitialBuffer = 8 * 1024;

/**
 * @brief 缓冲区上限
 *
 * 由 4 MB 上调到 12 MB。原因不是"多给点总没错"，而是有一个具体的
 * 满载需求装不下：
 *
 *   服务端 `kMaxHistoryLimit` = 10000 点（这是任何窗口的硬上界）
 *   真机实测每行 JSON 约 784 字节（kBoardRealHistory 的字段形状）
 *   → 10000 × 784 ≈ 7.5 MB，超过原上限 4 MB。
 *
 * 超过上限时的行为是**报错**（不是静默截断），所以原有代码不会给出假数据；
 * 代价是满载查询永远失败。既然时间窗切换是白名单批准的现场功能，
 * 就得让它真能工作。
 *
 * ## 为什么按 10000 点算而不是按某个窗口的常态算
 *
 * 板端实测（2026-11-08）：24h 请求在历史有大量空档时只取回 2610 条 /
 * 2.19 MB。若按这个常态定上限，就会在设备连续运行、数据变密之后突然失败。
 * 稀疏是偶然，满载才是要保证的上界。
 *
 * 取 12 MB 而不是刚好 7.5 MB：留出约 1.6 倍余量，因为
 *   - 每行含 iface / rssi_source / score_model 等字符串字段，长度可变
 *   - 全部网卡查询（interface 为空）时行数不变但字段可能更长
 *   - assessment_profile 从 UNSPECIFIED 变成 INTERNET_ACCESS 会让每行长几字节
 *
 * 内存代价：这块缓冲只存在于取数线程的栈外堆上，且只在一次调用期间存在，
 * 板端（1GB+ 内存）完全承受得起。相比之下，静默少画几个小时更不可接受。
 */
constexpr size_t kMaxBuffer = 12 * 1024 * 1024;

/// 错误信息缓冲区大小
constexpr size_t kErrorBufferSize = 512;

} // namespace

DataSource::DataSource() = default;

DataSource::~DataSource() {
    cleanup();
}

bool DataSource::init() {
    if (initialized_) {
        return true;
    }
    last_error_.clear();
    if (!weaknet_init()) {
        // 必须 cleanup，否则本层将永久卡死在失败状态。
        //
        // weaknet_init() 在 client.cpp:1348 的实现是：g_client 非空时直接
        // return g_client->isConnected()，而 connected_ 只在 initConnection()
        // 里赋值一次。连接失败后 g_client 仍留在全局，于是后续每次
        // weaknet_init() 都走 "already initialized" 分支、永远返回 false。
        //
        // weaknet_cleanup() 把 g_client 置空并 disconnect，下一次 init() 才会
        // 真正重建连接。副作用是它会调用 Logger::shutdown()，下次 init 再
        // InitGoogleLogging()——已实测 Init/Shutdown 反复循环安全。
        weaknet_cleanup();
        last_error_ = "weaknet_init() failed: cannot establish D-Bus connection";
        return false;
    }
    initialized_ = true;
    return true;
}

void DataSource::cleanup() {
    if (initialized_) {
        // weaknet_cleanup() 释放内部 D-Bus 连接。
        // 多次调用是安全的，但这里仍用标志位确保配对。
        weaknet_cleanup();
        initialized_ = false;
    }
}

// ---------------------------------------------------------------------------
// 通用取数模板
// ---------------------------------------------------------------------------

template <typename Caller>
FetchResult DataSource::invoke(Caller caller) const {
    FetchResult result;

    if (!initialized_) {
        result.error = "DataSource not initialized; call init() first";
        return result;
    }

    std::vector<char> buffer(kInitialBuffer, '\0');
    std::vector<char> error(kErrorBufferSize, '\0');

    while (true) {
        // 每轮重置，避免上一轮的残留内容干扰判断
        std::fill(buffer.begin(), buffer.end(), '\0');
        std::fill(error.begin(), error.end(), '\0');

        const bool ok = caller(buffer.data(), buffer.size(),
                               error.data(), error.size());

        // error 缓冲区非空表示服务端或库层报了明确错误
        const std::string error_text(error.data());

        if (!ok) {
            result.error = error_text.empty()
                               ? "C API returned false without error message"
                               : error_text;
            result.json.assign(buffer.data());
            return result;
        }

        // 成功时要确认内容完整：C API 不报告截断，只能自己判断。
        // 判定标准：非空，且 JsonReader 认为结构闭合。
        std::string candidate(buffer.data());

        if (candidate.empty()) {
            result.error = "C API returned true but buffer is empty";
            return result;
        }

        // 内容长度接近缓冲区上限 → 极可能被截断，扩大重试
        const bool near_full = candidate.size() + 1 >= buffer.size();
        JsonReader reader(candidate);
        const bool complete = reader.valid();

        if (complete && !near_full) {
            result.ok = true;
            result.json = std::move(candidate);
            return result;
        }

        if (buffer.size() >= kMaxBuffer) {
            // 已达上限仍不完整：如实报告，不假装成功
            result.error = "response exceeds max buffer (" +
                           std::to_string(kMaxBuffer) + " bytes) or is malformed";
            result.json = std::move(candidate);
            return result;
        }

        buffer.resize(buffer.size() * 2);
    }
}

// ---------------------------------------------------------------------------
// 具体接口
// ---------------------------------------------------------------------------

FetchResult DataSource::fetch_experience_raw() const {
    return invoke([](char* b, size_t n, char* e, size_t en) {
        return weaknet_get_network_experience(b, n, e, en);
    });
}

FetchResult DataSource::fetch_diagnosis_raw() const {
    return invoke([](char* b, size_t n, char* e, size_t en) {
        return weaknet_get_diagnosis(b, n, e, en);
    });
}

FetchResult DataSource::fetch_history_raw(const std::string& interface,
                                          int limit,
                                          const std::string& start,
                                          const std::string& end) const {
    return invoke([&interface, limit, &start, &end](char* b, size_t n, char* e,
                                                    size_t en) {
        // start / end 传空串表示不限时间范围
        return weaknet_get_history(interface.c_str(), start.c_str(), end.c_str(),
                                   limit, b, n, e, en);
    });
}

} // namespace dashboard
} // namespace weaknet

/**
 * @file dashboard_data.hpp
 * @brief Qt 看板使用的 POD 数据结构
 *
 * ## 数据来源
 *
 * 全部来自现有 D-Bus 只读方法，经 `client/weaknet_client.h` 的 C API 获取：
 *
 *   weaknet_get_network_experience()  → ExperienceSnapshot
 *   weaknet_get_diagnosis()           → DiagnosisSnapshot
 *   weaknet_get_history()             → vector<HistoryPoint>
 *
 * 不新增 D-Bus 方法，不修改服务端。
 *
 * ## 为什么单独定义 POD
 *
 * 参考 `monitor_system` 的 `monitor_data.h` 做法：**把传输层挡在 UI 之外**。
 *
 * 直接让 UI 解析 JSON 的后果：
 *   - JSON 字段改名 → 改 UI 代码
 *   - UI 代码里出现大量 `getString("overall.state")` 这类魔法字符串
 *   - 无法对数据映射逻辑做单元测试
 *
 * 分离后：
 *   - JSON → POD 是纯函数，可独立单测
 *   - UI 只读 POD，不知道 JSON 长什么样
 *
 * ## 字段与 schema v2 的对应
 *
 * schema v2 的实际形状由 `server/include/assurance/legacy_adapter.hpp:162`
 * 的 `toExperienceJsonV2()` 定义。本文件的字段与之逐项对应。
 */

#ifndef WEAKNET_QT_DASHBOARD_DASHBOARD_DATA_HPP
#define WEAKNET_QT_DASHBOARD_DASHBOARD_DATA_HPP

#include <cstdint>
#include <string>
#include <vector>

namespace weaknet {
namespace dashboard {

/**
 * @brief 单个维度的 SLE 评估结果
 *
 * 对应 JSON: `network_health.ip_reachability` 等
 */
struct SleItem {
    /// 维度标识（如 "ip_reachability"、"dns"）
    std::string key;

    /// 状态：GOOD / DEGRADED / BAD / UNKNOWN
    ///
    /// 取值来自 `server/include/assurance/health_state.hpp:15-23`
    /// 的 `healthStateToString()`。注意不是 HEALTHY/FAILED。
    std::string state;

    /// 覆盖率：FULL_FOR_PROFILE / PARTIAL / NONE
    ///
    /// 取值来自同文件 `coverageToString()`（`:31-38`）。注意不是 FULL。
    std::string coverage;

    /// 适用性：APPLICABLE / NOT_APPLICABLE
    std::string applicability;

    /// 原因说明（机器可读 token）
    std::string reason;

    /// 是否携带有效评估（state != UNKNOWN 且 coverage != NONE）
    bool has_value() const {
        return state != "UNKNOWN" && !state.empty();
    }

    /// 该维度是否适用于当前链路形态（如 RF Health 在有线链路下不适用）
    bool applicable() const { return applicability != "NOT_APPLICABLE"; }
};

/**
 * @brief 网络体验快照（schema v2）
 *
 * 对应 `GetNetworkExperience` 的返回。
 *
 * **注意**：服务端在无快照或快照过期时返回的是
 * `{"schema_version":2,"state":"UNKNOWN","coverage":"NONE","reason":"..."}`，
 * 此时顶层没有 `overall` 对象。解析时需兼容这种形状。
 */
struct ExperienceSnapshot {
    int schema_version = 0;

    /// 被评估的网卡名（如 "wlan0"）
    std::string interface_name;

    /// 评估档位（如 "FULL" / "PARTIAL"）
    std::string assessment_profile;

    // --- overall ---
    std::string overall_state = "UNKNOWN";
    std::string overall_coverage = "NONE";
    double display_score = 0.0;

    // --- network_health（4 项）---
    SleItem ip_reachability;
    SleItem responsiveness;
    SleItem reliability;
    SleItem rf_health;

    // --- service_health（9 项）---
    SleItem dns_service;
    SleItem tcp_connect;
    SleItem tcp_rtt;
    SleItem http_access;
    SleItem captive_portal;
    SleItem active_dns;
    SleItem active_tcp;
    SleItem active_https;
    SleItem active_portal;

    /// 警告列表
    std::vector<std::string> warnings;

    /// 首要问题（无则为空）
    std::string primary_issue;

    /// 顶层失效原因（无快照 / 快照过期时非空）
    std::string unavailable_reason;

    /**
     * @brief 是否是可展示的有效快照
     *
     * 服务端返回 UNKNOWN 时（no_assessment_yet / stale_assessment），
     * 看板应显示「等待评估」而不是空白或 0 分。
     */
    bool available() const {
        return unavailable_reason.empty() && overall_state != "UNKNOWN";
    }

    /// 按状态汇总各维度计数：健康 / 降级 / 失败 / 未知
    void count_by_state(int* healthy, int* degraded, int* failed, int* unknown) const;
};

/**
 * @brief 被排除的候选原因
 *
 * 对应 JSON: `excluded_causes[].{cause,reason}`
 */
struct ExcludedCause {
    std::string cause;
    std::string reason;
};

/**
 * @brief 建议动作
 *
 * 对应 JSON: `actions[].{priority,action_id,params}`
 *
 * 只是**建议**。真正执行必须走 `weaknet_execute_action()`，
 * 且该 D-Bus 方法要求 root 权限（`dbus_service.cpp:requireRootCaller`）。
 * 看板不自行执行任何动作。
 */
struct ActionSuggestion {
    int priority = 1;
    std::string action_id;
};

/**
 * @brief 诊断结论快照
 *
 * 对应 `GetDiagnosis` 的返回（DiagnosisFacts JSON）。
 *
 * 字段逐项依据 `server/include/assurance/diagnosis_engine.hpp:44-85`
 * 的 `DiagnosisFacts::toJson()`：
 *
 * ```json
 * {"fault_domain":"...","primary_issue":"...","confidence":"HIGH|MEDIUM|LOW",
 *  "secondary_issues":["..."],"evidence_refs":["..."],
 *  "excluded_causes":[{"cause":"...","reason":"..."}],
 *  "actions":[{"priority":1,"action_id":"...","params":{...}}],
 *  "default_summary_template":"..."}
 * ```
 *
 * 注意 `confidence` 是**字符串枚举**，不是数值。
 */
struct DiagnosisSnapshot {
    /// 是否成功取得诊断
    bool valid = false;

    /// 故障域（如 "DNS" / "RF" / "TCP" / "HTTP" / "NONE"）
    std::string fault_domain;

    /// 首要问题描述（机器 token）
    std::string primary_issue;

    /// 置信度：HIGH / MEDIUM / LOW
    std::string confidence = "LOW";

    /// 次要问题
    std::vector<std::string> secondary_issues;

    /// 引用的证据 ID
    std::vector<std::string> evidence_refs;

    /// 被排除的候选原因
    std::vector<ExcludedCause> excluded_causes;

    /// 建议动作
    std::vector<ActionSuggestion> actions;

    /// 人读摘要模板
    std::string summary_template;
};

/**
 * @brief 历史趋势可切换的指标
 *
 * ## 为什么是这 5 个
 *
 * `network_history` 表里还有 `traffic_bps` / `flows` / `tcp_conn_active` 等
 * 十余个数值列（见 `server/src/database_manager.cpp` 的 `queryHistory()`
 * SELECT 列表），但现场交互终端的能力白名单只批准「趋势指标切换」一项。
 * 每多一个指标就多一份「这个轴该怎么读」的解释成本，而现场要的是
 * 秒级确认，不是分析工具。
 *
 * 选这 5 个是因为它们覆盖了三个层次，且每个都对应一个现场会问的问题：
 *
 * | 指标 | 层次 | 现场问题 |
 * | --- | --- | --- |
 * | Score | 整体结论 | 到底好不好 |
 * | Rtt | 响应性 | 慢不慢 |
 * | Jitter | 稳定性 | 抖不抖 |
 * | Rssi | 射频物理层 | 信号够不够 |
 * | TcpLoss | 传输层 | 丢不丢包 |
 *
 * ## 13 个 SLE 维度为什么进不来
 *
 * `ip_reachability` / `dns` / `tcp_connect` 等 SLE 维度在 `network_history`
 * 表里**没有存储列**——落库的是原始测量值，SLE 结论只在实时评估里算出来。
 * 想画 SLE 维度的趋势必须新增服务端存储表面，那是独立规划范围。
 */
enum class HistoryMetric {
    Score,
    Rtt,
    Jitter,
    Rssi,
    TcpLoss,
};

/**
 * @brief 各指标的「未测量」哨兵值
 *
 * ## 为什么不用 0，也不用 NaN
 *
 * 1. **0 是合法值**。`tcp_loss = 0` 表示「测了，没丢包」，与「没测」是
 *    完全不同的事；把它俩混成同一个 0，界面就会把「无观测」画成「完美」。
 * 2. **NaN 会污染比较**。`std::min_element` / `<` 遇到 NaN 的结果不确定，
 *    且服务端本来就没用 NaN。
 *
 * 因此这里沿用服务端自己的哨兵语义，不做第二套约定：
 * `server/include/net_info.hpp:237` 写的是
 * `tcp_loss_rate_ = -1.0 表示未测量`，`database_manager.cpp` 用 `-1000`
 * 表示 rssi 缺失。解析层只是把 JSON 的 `null` 翻译成同一套哨兵。
 */
constexpr double kNoRttMs = -1.0;
constexpr double kNoJitterMs = -1.0;
constexpr double kNoRssiDbm = -1000.0;
constexpr double kNoTcpLossPct = -1.0;

/// 某指标的取值是否为「未测量」哨兵
bool is_history_metric_absent(HistoryMetric metric, double value);

/**
 * @brief 历史趋势的单个数据点
 *
 * 对应 `GetHistory` 返回的数组元素。
 *
 * 字段名依据 `server/src/database_manager.cpp` 的 `queryHistory()` 实际输出。
 * 注意 `ts` 是 **字符串** 而不是数字（SQLite 里按 TEXT 存），形如
 * `"2026-11-05T13:27:00"`（`currentTimestamp()` 用 `%Y-%m-%dT%H:%M:%S`，
 * 带 T 分隔；此处早先注释写成空格分隔是错的，真机样本已确认）。
 */
struct HistoryPoint {
    /// 采样时间（字符串，来自 `ts` 字段）
    std::string ts;

    /// 该时刻的综合分（来自 `score`，与 `overall_score` 同值）
    double score = 0.0;

    /// 该行是否为 v2 之前的历史数据（来自 `legacy`，即 `data_version < 2`）
    ///
    /// 关键语义：v1 用的是旧的加权模型，同一分数在不同模型下**不可直接比较**。
    /// 图表必须把它画得与 v2 点不同，否则会读出一条不存在的趋势。
    bool legacy = false;

    /// 往返时延（毫秒）；`kNoRttMs` 表示未测量
    double rtt_ms = kNoRttMs;

    /// 抖动（毫秒）；`kNoJitterMs` 表示未测量
    double jitter_ms = kNoJitterMs;

    /// RSSI（dBm，负值）；`kNoRssiDbm` 表示未测量
    double rssi_dbm = kNoRssiDbm;

    /// TCP 丢包率（**百分比**，0-100）；`kNoTcpLossPct` 表示未测量
    ///
    /// 单位是 % 不是 0-1 比率，依据 `server/include/net_info.hpp:237` 的
    /// `tcp_loss_rate_（%）` 以及 `reliability_evaluator.hpp:13-14` 的
    /// 阈值 `tcp_loss_good_max{1.0}` / `tcp_loss_bad_min{4.0}`（都是百分数）。
    double tcp_loss = kNoTcpLossPct;

    /// 取某指标的值（未测量时返回对应哨兵，不返回 0）
    double value(HistoryMetric metric) const;

    /// 某指标在此点是否有有效值
    bool has(HistoryMetric metric) const {
        return !is_history_metric_absent(metric, value(metric));
    }
};

/**
 * @brief 历史趋势序列
 *
 * 不携带网卡名：查询「全部网卡」时任意一条记录的 iface 都不代表整个序列，
 * 请求侧的网卡由调用方（MainWindow::interface_）持有。
 */
struct HistorySeries {
    std::vector<HistoryPoint> points;

    /// 该序列里某指标的有效点数量（哨兵值不计）
    int count_with(HistoryMetric metric) const;
};

/**
 * @brief 指标的显示名（中文，用于图标题与下拉框）
 */
const char* history_metric_label(HistoryMetric metric);

/**
 * @brief 指标的单位后缀（如 "ms" / "dBm" / "%"），无量纲返回空串
 */
const char* history_metric_unit(HistoryMetric metric);

/**
 * @brief Y 轴的建议取值范围 {lo, hi}
 *
 * ## 为什么不让图表一律按数据自适应
 *
 * 分数 0-100 自适应是对的：它本身就是归一化量纲，看相对起伏即可。
 *
 * 但 RSSI 不行。真机 RSSI 常在 -40 到 -70 dBm 之间波动，若按数据自适应，
 * -45 与 -50 会被拉满整个绘图区，看上去像断崖。而这两个值的实际差别
 * 在工程上几乎无意义（都属于「信号很好」）。对这类有绝对含义的指标，
 * 必须钉住一个物理上有意义的范围，让「波动幅度」看起来就是它本来的大小。
 *
 * 同理 RTT：自适应会把 25ms↔30ms 放大成满屏落差，而现场关心的是
 * 「有没有超过 100ms」这个量级。
 *
 * @return 固定范围；返回 {0, 0} 表示调用方应按数据自适应（仅 Score）
 */
struct HistoryRange {
    double lo = 0.0;
    double hi = 0.0;
    bool fixed = false;
};

HistoryRange history_metric_range(HistoryMetric metric);

/**
 * @brief 现场终端的三个时间窗
 *
 * ## 为什么是 1h / 6h / 13h
 *
 * 上限硬约束：服务端 `kMaxHistoryLimit = 10000`
 * （`server/src/dbus_service.cpp:1515`），落库周期 5 秒（见下方
 * `kHistorySampleIntervalSeconds`），因此最长连续覆盖 = 10000 × 5s
 * ≈ 13.89 小时。
 *
 * 13h 需要 9360 点，在上限内且留了 640 点余量；6h 需 4320 点；1h 需 720 点。
 *
 * ## 为什么原本写的是 24h，以及为什么改掉
 *
 * 产品定位 v1.2 的白名单原文是「1h / 6h / 24h」。但 24h 按 5 秒落库需要
 * 17280 点，**超出上限 73%**，服务端会静默钳到 10000 条：标签写 24h、
 * 图里只有 13.9h。板端实测已确认这个钳制行为（请求 7 天 / limit=20000
 * 时恰好返回 10000 条、跨度 69.99h）。
 *
 * 挂一个必然说谎的 24h 按钮，比少一个窗口更坏——现场会据此判断「过去一天
 * 都正常」，而实际上那 10 小时压根没被看到。因此把最大窗口定在服务端能力
 * 边界内的 13h，并同步订正产品定位与权责契约文档。
 *
 * > 这不是「能力退化」，而是把假能力换成真能力：13h 全量可见 > 24h 只看到 14h。
 *
 * ## 为什么窗口定义放在数据层
 *
 * 「13h 窗口要请求多少个点」是一个**可验证的推算**，不是 UI 的风格选择：
 * 它由落库周期和服务端 limit 上限共同决定。放在 UI 里就只能靠
 * 人肉 review，放在这里可以单测——尤其是「不超过 10000」这条硬约束。
 */
enum class HistoryWindow {
    Last1h,
    Last6h,
    Last13h,
};

/**
 * @brief 服务端写库周期（秒）
 *
 * ## 这个值不是「采集间隔」，别再把两者混为一谈
 *
 * 板上同时存在三个不同的周期，很容易搞混：
 *
 * | 周期 | 值 | 出处 |
 * | --- | --- | --- |
 * | 各监控器采集 | 3~30 秒不等（多为 10 秒） | `config.yaml` 的 `interval_ms` |
 * | **网络历史落库** | **5 秒（硬编码）** | `server/src/server.cpp` `start_history_persistence_thread()` |
 * | 看板请求点数 | 窗口秒数 / 本常量 | 本文件 |
 *
 * 本常量必须等于**第二行**，因为 `network_history` 表里的行是落库线程写的，
 * 与监控器多久采一次无关。
 *
 * ## 踩过的坑
 *
 * 初版把这个常量当成 10（依据 CLAUDE.md「数据采集间隔：10 秒」），
 * 于是 24h 只请求 8640 条。而板端实测（2026-11-08，直调 `libweaknet`
 * 取 20 分钟样本）相邻记录间隔中位数 **5.0 秒**、最大 6.0 秒。
 * 服务端 `ORDER BY ts DESC LIMIT ?` 先倒序再截断，点给少了一半，
 * 24h 窗口实际只画到约 12 小时——标签与图形不一致。
 */
constexpr int kHistorySampleIntervalSeconds = 5;

/// 该窗口覆盖的秒数
int history_window_seconds(HistoryWindow window);

/**
 * @brief 该窗口应请求的条数
 *
 * = 窗口秒数 / 落库周期。三个窗口分别得到 720 / 4320 / 9360，
 * **全部低于服务端 10000 上限**——这是本函数存在的主要理由，
 * 单测会守住这条不变量，防止有人加窗口时忘记算。
 */
int history_window_limit(HistoryWindow window);

/// 界面标签（如 "1 小时"）
const char* history_window_label(HistoryWindow window);

/**
 * @brief 历史查询的起始时间串
 *
 * @param window 时间窗
 * @param now_epoch_seconds 当前时间（Unix 秒）。**显式传入而不是内部取时钟**：
 *        这样才能对结果做断言，否则单测只能验证「格式像」，验证不了「真的是 1 小时前」。
 * @return 形如 "2026-11-08T09:30:00" 的时间串（**本地时间**，与
 *         `database_manager.cpp` 的 `currentTimestamp()` 用 `localtime_r` 一致）。
 *         若换算失败返回空串，调用方应退化成「不限时间」。
 */
std::string history_window_start(HistoryWindow window, long long now_epoch_seconds);

// ---------------------------------------------------------------------------
// 解析函数（JSON 字符串 → POD）
// ---------------------------------------------------------------------------

/**
 * @brief 解析 schema v2 体验快照 JSON
 *
 * @param json `weaknet_get_network_experience()` 返回的字符串
 * @return 解析结果；输入无效时返回默认构造对象（available() 为 false）
 */
ExperienceSnapshot parse_experience(const std::string& json);

/**
 * @brief 解析诊断事实 JSON
 */
DiagnosisSnapshot parse_diagnosis(const std::string& json);

/**
 * @brief 解析历史趋势 JSON
 *
 * 服务端 `GetHistory` 实际返回的是顶层数组，见
 * `server/src/database_manager.cpp:686-744`。数据库不可用时返回
 * `{"error":"database not available"}`（对象而非数组），此时返回空序列。
 *
 * 各点按 `ORDER BY ts DESC` 逆序排列，这里统一翻转为时间正序，
 * 便于图表从左到右绘制。
 */
HistorySeries parse_history(const std::string& json);

} // namespace dashboard
} // namespace weaknet

#endif // WEAKNET_QT_DASHBOARD_DASHBOARD_DATA_HPP

/**
 * @file data_source.hpp
 * @brief 取数层：调用 libweaknet 的 C API 拿原始 JSON
 *
 * ## 为什么单独一层
 *
 * 数据层（`parse_xxx`）只做 JSON → POD 的纯转换，它不知道数据从哪来。
 * 取数层负责「去拿 JSON」这件事，是唯一直接调用 `weaknet_*` 的地方。
 * 解析由调用方（主线程槽函数）调 `parse_xxx()` 完成，本层不解析。
 *
 * 分开的好处：数据层可以在没有 D-Bus、没有服务端的机器上单测；
 * 取数层可以在板端用真实服务验证。
 *
 * ## 为什么必须后台线程
 *
 * `weaknet_get_*` 内部走 D-Bus 同步调用（`dbus_connection_send_with_reply_and_block`），
 * 在服务端忙或 D-Bus 卡住时会阻塞数秒。如果在 Qt 主线程调用，界面会冻结。
 *
 * ## 缓冲区策略
 *
 * C API 的签名是 `(buffer, buffer_size, error_buffer, error_size)`，
 * 返回值只表示调用成败，不告诉你需要多大缓冲区。看板的 JSON 可能较大
 * （schema v2 快照含 13 个维度 + evidence，历史 100 条），因此采用
 * **先试小缓冲区、遇到疑似截断就扩大重试**的策略。
 *
 * 注意：C API 没有明确的「缓冲区不足」错误码，截断时可能返回 true 但
 * JSON 不完整。因此这里用 `JsonReader::valid()` 判断完整性，不合法就翻倍重试。
 */

#ifndef WEAKNET_QT_DASHBOARD_DATA_SOURCE_HPP
#define WEAKNET_QT_DASHBOARD_DATA_SOURCE_HPP

#include <cstddef>
#include <string>

namespace weaknet {
namespace dashboard {

/**
 * @brief 一次取数操作的结果
 *
 * 把「成功/失败」和「失败原因」显式分开，避免调用方拿着空字符串猜。
 */
struct FetchResult {
    /// C API 是否返回成功
    bool ok = false;

    /// 失败原因（ok 为 true 时为空）
    std::string error;

    /// 原始 JSON（调试用；失败时可能为空或被截断）
    std::string json;
};

/**
 * @brief 取数层
 *
 * 所有方法都是**阻塞**的，必须在后台线程调用，不要放在 UI 线程。
 */
class DataSource {
public:
    DataSource();
    ~DataSource();

    // 禁止拷贝：内部持有 weaknet_init/cleanup 的配对状态
    DataSource(const DataSource&) = delete;
    DataSource& operator=(const DataSource&) = delete;

    /**
     * @brief 初始化 libweaknet 并建立 D-Bus 连接
     *
     * 幂等：已成功初始化后重复调用直接返回 true。
     *
     * **失败后可重试**：失败路径内部会调用 `weaknet_cleanup()` 把库的全局
     * 客户端置空，因此可以隔一段时间再次调用 `init()` 真正重连，而不是
     * 永远停留在同一个失败结果上。板端开机早期 D-Bus 尚未就绪时依赖这一点。
     *
     * @return true 成功；false 失败（可用 last_error() 取原因）
     */
    bool init();

    /**
     * @brief 释放 D-Bus 连接
     *
     * 析构时自动调用。
     */
    void cleanup();

    /// 最近一次 init() 失败的原因
    const std::string& last_error() const { return last_error_; }

    // -----------------------------------------------------------------------
    // 取数接口（全部阻塞）
    // -----------------------------------------------------------------------

    /**
     * @brief 取网络体验快照（schema v2）
     *
     * 对应 D-Bus `GetNetworkExperience`。
     * 服务端在无快照时也会返回合法的 UNKNOWN JSON，调用方用
     * `parse_experience()` + `available()` 判断，不在这里解析。
     */
    FetchResult fetch_experience_raw() const;

    /**
     * @brief 取诊断事实
     */
    FetchResult fetch_diagnosis_raw() const;

    /**
     * @brief 取历史趋势
     *
     * @param interface 网卡名；空字符串表示全部
     * @param limit     最多返回条数（服务端上限 10000，且 <=0 会被钳制为 1）
     * @param start     起始时间（含），格式与 `ts` 列一致 `%Y-%m-%dT%H:%M:%S`；
     *                  空串表示不限
     * @param end       结束时间（含），同上
     *
     * ## start/end 的真实语义
     *
     * `server/src/database_manager.cpp` 的 `queryHistory()` 把它们拼成
     * `ts >= ?` / `ts <= ?`，**不是**降采样、不是聚合。因此
     * 「取最近 6 小时」= 算出一个 start 时间串 + 给一个足够大的 limit。
     *
     * ## limit 与时间窗必须同时给足，缺一不可
     *
     * 服务端是 `ORDER BY ts DESC LIMIT ?`——先按时间倒序，再截断。
     * 若 start 给 13 小时前、limit 只给 720，返回的是
     * **最新 720 条**（落库周期 5 秒 → 只有 1 小时），
     * 标签写着 13h、图里只有 1h。这是数据保真度上的谎报，比多花几 MB 内存坏得多。
     *
     * 所以 limit 必须按 `窗口秒数 / 落库周期` 算足：
     *
     * | 窗口 | 落库周期 | 需要的点 | 服务端上限 10000 |
     * | --- | --- | --- | --- |
     * | 1h  | 5s | 720  | 够 |
     * | 6h  | 5s | 4320 | 够 |
     * | 13h | 5s | 9360 | 够（留 640 余量） |
     *
     * ## 为什么最大窗口是 13h 而不是 24h
     *
     * 上限 10000 条 × 5 秒 = 50000 秒 ≈ 13.89 小时，这就是服务端能给的
     * 最大连续覆盖。24h 需要 17280 条，超出上限 73%，会被**静默钳制**到
     * 10000 条——板端实测：请求 7 天 / `limit=20000` 时恰好返回 10000 条、
     * 跨度 69.99h 而非请求的 7 天。所以界面不提供 24h 与 7d，而不是
     * 挂一个必然说谎的按钮。
     *
     * ## 字节数是上界，不是常态
     *
     * 板端实测（2026-11-08）：24h 请求在历史有大量空档时只取回 2610 条 /
     * 2.19 MB；而 10000 条满载约 7.5 MB。`kMaxBuffer` 按**满载上界**定，
     * 因为稀疏是偶然、连续运行才是常态。
     *
     * 缓冲区的 `kMaxBuffer` 已按满载体积上调（见 data_source.cpp）。
     */
    FetchResult fetch_history_raw(const std::string& interface, int limit,
                                  const std::string& start = std::string(),
                                  const std::string& end = std::string()) const;

private:
    /**
     * @brief 通用取数模板：调用 C API 并按需扩大缓冲区
     *
     * @param caller 形如 `[](char* b, size_t n, char* e, size_t en) { return weaknet_xxx(b, n, e, en); }`
     */
    template <typename Caller>
    FetchResult invoke(Caller caller) const;

    bool initialized_ = false;
    std::string last_error_;
};

} // namespace dashboard
} // namespace weaknet

#endif // WEAKNET_QT_DASHBOARD_DATA_SOURCE_HPP

/**
 * @file main_window.hpp
 * @brief 看板主窗口
 *
 * ## 布局
 *
 * ```
 * ┌─────────────────────────────────────────────┐
 * │ [刷新] wlan0  GOOD 85.2  2026-11-05 20:31   │  ← 顶栏
 * ├──────────────┬──────────────────────────────┤
 * │ 网络健康      │                              │
 * │  IP 可达  ●  │      历史趋势折线图            │
 * │  响应性   ●  │                              │
 * │  可靠性   ●  │                              │
 * │  RF 健康  ○  │                              │
 * ├──────────────┤                              │
 * │ 服务健康      │                              │
 * │  DNS      ●  │                              │
 * │  TCP 连接 ●  │                              │
 * │  ...         │                              │
 * ├──────────────┴──────────────────────────────┤
 * │ 诊断：故障域 DNS · 首要问题 dns_timeout      │  ← 底栏
 * └─────────────────────────────────────────────┘
 * ```
 *
 * ## 状态色的取值依据
 *
 * `server/include/assurance/health_state.hpp:15-23`：
 * GOOD / DEGRADED / BAD / UNKNOWN。
 */

#ifndef WEAKNET_QT_DASHBOARD_MAIN_WINDOW_HPP
#define WEAKNET_QT_DASHBOARD_MAIN_WINDOW_HPP

#include <QByteArray>
#include <QMainWindow>
#include <QString>

#include "data/dashboard_data.hpp"

class QComboBox;
class QHBoxLayout;
class QLabel;
class QPushButton;

namespace weaknet {
namespace dashboard {

class DataFetchThread;
class LineChartWidget;

/**
 * @brief 看板主窗口
 */
class MainWindow : public QMainWindow {
    Q_OBJECT

public:
    explicit MainWindow(QWidget* parent = nullptr);
    ~MainWindow() override;

    /**
     * @brief 启动后台取数与自动刷新
     *
     * 不从构造函数调用：构造时窗口还没显示，立刻取数会拖慢启动。
     */
    void start();

    /**
     * @brief 指定历史趋势查询的网卡，并据此设置图表标题
     *
     * 空字符串表示不限制（服务端按全部网卡返回），标题会写成「全部网卡」。
     *
     * 必须在 `start()` 之前调用。`main.cpp` **无条件调用**（不传 `-i` 时传空串）：
     * 它同时把网卡与当前时间窗同步给取数线程并重算标题，跳过调用会让
     * 标题与实际查询范围对不上。
     */
    void setInterface(const QString& interface_name);

    // -----------------------------------------------------------------------
    // 展示态的可观测面
    //
    // 这两个是**只读访问器**，给测试与将来可能的持久化用。
    // 不提供 setter：所有写入路径都必须走 onMetricSelected() /
    // onWindowSelected()，那两个函数里带着「切换不能重置另一维」的约束。
    // 一旦开了 setter，这个约束就没有守卫了。
    // -----------------------------------------------------------------------

    /// 当前绘制的指标
    HistoryMetric current_metric() const { return current_metric_; }

    /// 当前查询的时间窗
    HistoryWindow current_window() const { return current_window_; }

private slots:
    void onExperienceReady(const QByteArray& json);
    void onDiagnosisReady(const QByteArray& json);
    void onHistoryReady(const QByteArray& json);
    void onFetchFailed(const QString& stage, const QString& error);
    void onRefreshFinished();
    void onRefreshClicked();

    /// 指标选择器变更（白名单第 1 项）
    ///
    /// **只换视图，不重置时间窗**：用户先选「13 小时」再切到 RSSI，
    /// 期望看的仍然是 13 小时的 RSSI。
    void onMetricSelected(int index);

    /// 时间窗按钮点击（白名单第 2 项）
    ///
    /// **只换取数范围，不重置指标**，理由同上。
    void onWindowSelected(int window_id);

    /// 导出当前画面为 PNG（白名单第 3 项）
    void onExportClicked();

private:
    void build_ui();
    /// 顶栏右侧的展示态控制区（指标选择器 + 时间窗按钮 + 导出）
    void build_view_controls(QHBoxLayout* top);
    void apply_experience(const ExperienceSnapshot& snap);
    void apply_diagnosis(const DiagnosisSnapshot& snap);
    void update_status_label(const SleItem& item, QLabel* state_label,
                             QLabel* dot_label);
    static QString state_color(const QString& state);

    /// 重算图标题（网卡 + 指标 + 窗口），并把它交给 LineChartWidget
    void refresh_chart_title();

    /// 把当前画面存成 PNG，返回实际写入路径（失败为空）
    QString export_screenshot();

    DataFetchThread* fetcher_ = nullptr;
    LineChartWidget* chart_ = nullptr;

    /// 历史查询使用的网卡（空表示全部）。
    ///
    /// 这是**请求侧**的事实，不能从 `HistorySeries` 推断：
    /// 查询全部网卡时，任意一条记录的 iface 都不代表整个序列。
    /// 折线图标题直接用它，避免出现「标题写着 wlan0，实际混了 eth0」。
    QString interface_;

    // 顶栏
    QPushButton* refresh_button_ = nullptr;
    QLabel* iface_label_ = nullptr;
    QLabel* score_label_ = nullptr;
    QLabel* timestamp_label_ = nullptr;

    // -----------------------------------------------------------------------
    // 展示态控制（现场交互终端白名单的落地点）
    //
    // 产品定位 v1.2 允许现场改的只有「展示态」：看哪个指标、看多长时间、
    // 把当前画面导出。这三个控件就是那三项，**一个不多**。
    //
    // 绝对不在这里加的东西（违反白名单会直接越过权责契约）：
    //   - 触发 pending_actions / 执行动作
    //   - 改阈值、改配置
    //   - 重启服务、重连
    //   - 任何“就地算一个结论”的按钮
    //
    // 新增交互点前先读 `docs/产品定位-工业无线诊断网关.md` 第三节之二。
    // -----------------------------------------------------------------------

    /// 趋势指标选择器（白名单第 1 项）
    QComboBox* metric_combo_ = nullptr;

    /// 时间窗按钮（白名单第 2 项）：1h / 6h / 24h，互斥
    QPushButton* window_1h_button_ = nullptr;
    QPushButton* window_6h_button_ = nullptr;
    QPushButton* window_13h_button_ = nullptr;

    /// 截图导出（白名单第 3 项）
    QPushButton* export_button_ = nullptr;

    /// 当前展示的指标与时间窗。切换时二者互不干扰：
    /// 换窗口不能把指标重置，换指标也不能把窗口重置。
    HistoryMetric current_metric_ = HistoryMetric::Score;
    HistoryWindow current_window_ = HistoryWindow::Last1h;

    /// 各维度状态汇总「● 3 ● 2 ● 1 ○ 7」（count_by_state 的消费者）
    QLabel* summary_label_ = nullptr;
    /// 评估档位与覆盖度（assessment_profile 的消费者）
    QLabel* profile_label_ = nullptr;

    // 维度状态标签（顺序与 dashboard_data.hpp 中字段一致）
    QLabel* ip_reachability_label_ = nullptr;
    QLabel* responsiveness_label_ = nullptr;
    QLabel* reliability_label_ = nullptr;
    QLabel* rf_health_label_ = nullptr;

    QLabel* dns_label_ = nullptr;
    QLabel* tcp_connect_label_ = nullptr;
    QLabel* tcp_rtt_label_ = nullptr;
    QLabel* http_access_label_ = nullptr;
    QLabel* captive_portal_label_ = nullptr;
    QLabel* active_dns_label_ = nullptr;
    QLabel* active_tcp_label_ = nullptr;
    QLabel* active_https_label_ = nullptr;
    QLabel* active_portal_label_ = nullptr;

    // 每个维度左侧的状态圆点。
    //
    // 圆点与状态文本分别持有指针：`update_status_label()` 要在一次调用里
    // 同时给两者上色。改进前圆点由 `make_status_row()` 创建后就没再被引用，
    // 永远保持默认前景色，14 行扫下来看不出哪几项异常。
    QLabel* ip_reachability_dot_ = nullptr;
    QLabel* responsiveness_dot_ = nullptr;
    QLabel* reliability_dot_ = nullptr;
    QLabel* rf_health_dot_ = nullptr;

    QLabel* dns_dot_ = nullptr;
    QLabel* tcp_connect_dot_ = nullptr;
    QLabel* tcp_rtt_dot_ = nullptr;
    QLabel* http_access_dot_ = nullptr;
    QLabel* captive_portal_dot_ = nullptr;
    QLabel* active_dns_dot_ = nullptr;
    QLabel* active_tcp_dot_ = nullptr;
    QLabel* active_https_dot_ = nullptr;
    QLabel* active_portal_dot_ = nullptr;

    // 底栏
    //
    // experience 与 diagnosis 是**两个独立的异步数据源**，返回时序不定
    // （DataFetchThread 先发 experienceReady 再发 diagnosisReady，但二者
    // 都是队列连接，实际到达顺序不保证）。因此它们各自拥有独立控件：
    // 共用一个 QLabel 会让后到者覆盖先到者的内容。
    /// 体验快照的结论行：等待评估原因 / 首要问题（experience 独占）
    QLabel* experience_label_ = nullptr;
    /// 体验快照的警告（experience 独占，无警告时隐藏）
    QLabel* experience_detail_label_ = nullptr;
    /// 诊断结论行：故障域 + 置信度 + 动作数（diagnosis 独占）
    QLabel* diagnosis_label_ = nullptr;
    /// 诊断的人读摘要（diagnosis 独占，default_summary_template 的消费者）
    QLabel* summary_template_label_ = nullptr;
    /// 次要问题 / 已排除原因 / 证据（diagnosis 独占，可折叠）
    QLabel* diagnosis_extra_label_ = nullptr;
    QLabel* status_bar_label_ = nullptr;

    /// 本轮刷新是否出现过失败。
    ///
    /// 不能用「状态栏文字是否以『取数失败』开头」判断：那是跨轮持久的状态，
    /// 一旦出现过失败，之后即使每轮都成功也永远不会复位回「就绪」。
    /// 这里按轮记录，onRefreshFinished 时消费并清空。
    bool round_had_failure_ = false;

    bool refresh_in_flight_ = false;
};

