60	/// `QWidget` 要求进程内有 `QApplication`（`QGuiApplication` 不够）
61	class QtAppEnvironment : public ::testing::Environment {
62	public:
63	    void SetUp() override {
64	        static int argc = 1;
65	        static char arg0[] = "test_main_window";
66	        static char* argv[] = {arg0, nullptr};
67	
