85	/// 在窗口里按对象名找不到控件时，测试要给出可诊断的失败而不是崩
86	template <typename T>
87	T* find_child(QWidget& root, const char* name) {
88	    return root.findChild<T*>(QString::fromLatin1(name));
89	}
