91	/**
92	 * @brief 从三个可勾选的「1/6/24 小时」按钮里认出时间窗按钮
93	 *
94	 * 生产代码没给它们设 objectName（那只是为了测试方便，不该污染产品代码）。
95	 * 这里按「可勾选 + 文案是小时数」识别，是目前唯一不侵入产品的办法。
96	 * 若将来按钮文案改了，这条测试会明确报「找不到时间窗按钮」，
97	 * 而不是静默跳过——静默跳过等于这条测试不存在。
98	 */
99	QPushButton* window_button(QWidget& root, const QString& text) {
100	    const QList<QPushButton*> buttons = root.findChildren<QPushButton*>();
101	    for (QPushButton* b : buttons) {
102	        if (b->isCheckable() && b->text() == text) {
103	            return b;
104	        }
105	    }
106	    return nullptr;
107	}
