109	/// 走真实的 slider/dropdown 路径切指标：直接改下拉框索引，触发信号
110	void select_metric(MainWindow& w, HistoryMetric metric) {
111	    auto* combo = find_child<QComboBox>(w, "metric_combo");
112	    if (combo == nullptr) {
113	        // 生产代码没设 objectName，退回「窗口里唯一那个 QComboBox」
114	        const QList<QComboBox*> combos = w.findChildren<QComboBox*>();
115	        EXPECT_EQ(combos.size(), 1) << "主窗口应只有一个指标选择器";
116	        if (combos.isEmpty()) {
117	            return;
118	        }
119	        combo = combos.first();
120	    }
121	    const int index = combo->findData(static_cast<int>(metric));
122	    ASSERT_GE(index, 0) << "下拉框里没有这个指标条目";
123	    combo->setCurrentIndex(index);
124	}
