213	TEST(MainWindowTest, WindowButtonsAreMutuallyExclusive) {
214	    // 三个可勾选按钮必须始终恰好有一个亮着。
215	    // `setCheckable(true)` 的按钮被点一下会自己翻转，用户点「已选中的那个」
