248	TEST(MainWindowTest, CheckedWindowButtonLooksDifferent) {
249	    // 上一条测试只守了「恰好一个按钮 isChecked() == true」这个**逻辑**不变量。
250	    // 真机截图暴露出它不够：三个按钮的 `:hover` / `:pressed` 之外没有任何
251	    // 选中态样式，渲染出来边框与填充完全一致（实测三者的边框像素都是
252	    // `(224,227,232)`、内部都是 `(255,255,255)`）。现场用户看不出当前选的是
253	    // 哪个时间窗——控件存在、状态也对，但**这个状态不可见**。
254	    //
255	    // 判据不锚定具体配色（换主题不该让测试失败），只要求「选中与未选中
256	    // 的渲染结果必须可区分」。这条要求本身就是选中态的语义。
257	    // 必须先把产品主题装上去，否则量到的是 Fusion 原生样式。
258	    //
259	    // 这一点是本条测试第二版才想明白的：第一版没调 `apply_theme()`，
260	    // 而缺陷恰恰藏在**全局 QSS 覆盖**里（QSS 定义了 :hover/:pressed 却漏了
261	    // :checked，把原生样式里本该有的选中效果一并盖掉）。不装主题时
262	    // Fusion 原生的 checked 态自带高亮，测试于是 PASS——量到的不是
263	    // 产品真实渲染路径，缺陷被完美掩盖。
264	    weaknet::dashboard::apply_theme();
265	
266	    MainWindow w;
267	    w.setInterface(QString());
268	    w.resize(1024, 700);
269	    w.show();
270	    QApplication::processEvents();
271	
272	    auto render = [](QPushButton* b) {
273	        return b->grab().toImage().convertToFormat(QImage::Format_RGB32);
274	    };
275	    // 两图逐像素比较，返回不同的像素数。用「不同像素数」而不是「是否
276	    // 完全相同」，是为了让失败信息能说明差异有多小。
277	    auto diff_pixels = [](const QImage& a, const QImage& b) {
278	        if (a.size() != b.size()) {
279	            return static_cast<qint64>(a.width()) * a.height();
280	        }
281	        qint64 n = 0;
282	        for (int y = 0; y < a.height(); ++y) {
283	            for (int x = 0; x < a.width(); ++x) {
284	                if (a.pixel(x, y) != b.pixel(x, y)) {
285	                    ++n;
286	                }
287	            }
288	        }
289	        return n;
290	    };
291	
292	    QPushButton* b1 = window_button(w, QStringLiteral("1 小时"));
293	    QPushButton* b24 = window_button(w, QStringLiteral("24 小时"));
294	    ASSERT_NE(b1, nullptr);
295	    ASSERT_NE(b24, nullptr);
296	    ASSERT_TRUE(b1->isChecked()) << "初始应选中 1 小时";
297	    ASSERT_FALSE(b24->isChecked());
298	
299	    // 判据必须是**同一个按钮**在选中态与未选中态的渲染差。
300	    //
301	    // 不能拿「1 小时按钮」和「24 小时按钮」互相比：它们的文案本来就不同，
302	    // 像素必然不同——那样的断言恒真，什么缺陷都抓不到（第一版就是这么写的，
303	    // 在缺陷存在时照样 PASS）。只有固定同一个控件、只改 checked 状态，
304	    // 差异才唯一来自选中态样式。
305	    const QImage b1_checked = render(b1);
306	    const QImage b24_unchecked = render(b24);
307	
308	    // 切到 24 小时：b1 变为未选中、b24 变为选中
309	    b24->click();
310	    QApplication::processEvents();
311	    ASSERT_TRUE(b24->isChecked());
312	    ASSERT_FALSE(b1->isChecked());
313	
314	    const QImage b1_unchecked = render(b1);
315	    const QImage b24_checked = render(b24);
316	
317	    // (a) 未选中态的 b1 与选中态的 b1 必须不同
318	    const qint64 b1_delta = diff_pixels(b1_checked, b1_unchecked);
319	    EXPECT_GT(b1_delta, 100)
320	        << "时间窗按钮在选中与未选中之间渲染完全相同（" << b1_delta
321	        << " 像素不同）：checked 状态对用户不可见，现场无法判断当前时间窗";
322	
323	    // (b) checked → unchecked 再 checked 应回到同一外观（选中态是稳定的，
324	    //     不是「点一下换个随机色」）
325	    b1->click();
326	    QApplication::processEvents();
327	    ASSERT_TRUE(b1->isChecked());
328	    const qint64 round_trip = diff_pixels(b1_checked, render(b1));
329	    EXPECT_EQ(round_trip, 0) << "同一选中态两次渲染不一致，样式不稳定";
330	
331	    // (c) 反向：b24 的选中态也必须与它的未选中态可区分
332	    const qint64 b24_delta = diff_pixels(b24_unchecked, b24_checked);
333	    EXPECT_GT(b24_delta, 100)
334	        << "24 小时按钮的选中态与未选中态无法区分（" << b24_delta << " 像素不同）";
335	}
