338	// 截图导出（白名单第 3 项）
339	// ---------------------------------------------------------------------------
340	
341	TEST(MainWindowTest, ExportScreenshotWritesARealPng) {
342	    // 导出的核心承诺是「一定会给出一个能用的文件，并如实报告在哪」。
343	    // 这条测试走真实路径：调槽 → 抓图 → 落盘 → 回读校验 PNG 魔数。
344	    // 它不验证落在 U 盘还是 /tmp（那是环境决定的），只验证产物有效。
345	    MainWindow w;
346	    w.setInterface(QString());
347	    w.resize(1024, 700);
348	    w.show();
349	    QApplication::processEvents();
350	
351	    const bool invoked = QMetaObject::invokeMethod(
352	        &w, "onExportClicked", Qt::DirectConnection);
353	    ASSERT_TRUE(invoked) << "onExportClicked 必须是可被元对象调用的槽";
354	
355	    // 找出刚写的那个文件：在 /tmp 与 /media 下按前缀找最新的
356	    // （没有 U 盘时生产代码兜底到 /tmp，本机测试环境就是这种情况）
357	    QString found;
358	    const QString prefix = QStringLiteral("weaknet-dashboard-");
359	    const QStringList dirs = {QStringLiteral("/tmp"),
360	                              QStringLiteral("/media")};
361	    for (const QString& dir : dirs) {
362	        QDir d(dir);
363	        const QStringList entries =
364	            d.entryList(QStringList{prefix + QStringLiteral("*")}, QDir::Files,
365	                        QDir::Time);
366	        for (const QString& name : entries) {
367	            const QString path = d.filePath(name);
368	            // 只认本次测试生成的文件（30 秒内）
369	            if (QFileInfo(path).lastModified().secsTo(
370	                    QDateTime::currentDateTime()) <= 30) {
371	                found = path;
372	                break;
373	            }
374	        }
375	        if (!found.isEmpty()) {
376	            break;
377	        }
378	    }
379	
380	    ASSERT_FALSE(found.isEmpty()) << "导出后找不到任何 PNG 产物";
381	
382	    // 回读校验：`save()` 返回 true 但写出 0 字节也是可能的
383	    // （磁盘满、只读介质边界）。只看「文件存在」抓不到这种失败，
384	    // 必须真的把内容读出来认魔数。
385	    QFile f(found);
386	    ASSERT_TRUE(f.open(QIODevice::ReadOnly)) << "产物无法读取";
387	    const QByteArray head = f.read(8);
388	    const qint64 size = f.size();
389	    f.close();
390	
391	    // PNG 魔数：89 50 4E 47 0D 0A 1A 0A
392	    const QByteArray png_magic =
393	        QByteArray::fromHex("89504e470d0a1a0a");
394	    EXPECT_EQ(head, png_magic) << "产物不是合法 PNG";
395	    EXPECT_GT(size, 1024) << "PNG 太小，可能只写了头没有内容";
396	
397	    // 收尾：测试产物不留在磁盘上
398	    QFile::remove(found);
399	}
400	
401	TEST(MainWindowTest, ExportReportsTheActualPathOnStatusBar) {
402	    // 现场最危险的情形是「以为图存进 U 盘了，其实掉进了 tmpfs」。
403	    // 状态栏是唯一能让人知道这件事的地方，所以必须写**实际路径**，
404	    // 而且落在 /tmp 时要明确警告「重启即失」。
405	    MainWindow w;
406	    w.setInterface(QString());
407	    w.resize(1024, 700);
408	    w.show();
409	    QApplication::processEvents();
410	
411	    ASSERT_TRUE(QMetaObject::invokeMethod(&w, "onExportClicked",
412	                                          Qt::DirectConnection));
413	
414	    // 状态栏归 MainWindow 所有，是唯一那个 QStatusBar 里的 QLabel
415	    QStatusBar* bar = w.findChild<QStatusBar*>();
416	    ASSERT_NE(bar, nullptr);
417	    QString text;
418	    for (QLabel* label : bar->findChildren<QLabel*>()) {
419	        text = label->text();
420	        if (!text.isEmpty()) {
421	            break;
422	        }
423	    }
424	
425	    ASSERT_FALSE(text.isEmpty()) << "导出后状态栏什么都没说";
426	    EXPECT_TRUE(text.contains(QStringLiteral("截图已存")) ||
427	                text.contains(QStringLiteral("导出截图失败")))
428	        << "状态栏文案："
429	        << text.toStdString();
430	
431	    // 成功时必须带上完整路径（以 / 开头）与文件名前缀，
432	    // 否则用户不知道去哪里取图
433	    if (text.contains(QStringLiteral("截图已存"))) {
434	        EXPECT_TRUE(text.contains(QStringLiteral("/")))
435	            << "状态栏没给出实际路径：" << text.toStdString();
436	        EXPECT_TRUE(text.contains(QStringLiteral("weaknet-dashboard-")))
437	            << "状态栏没给出文件名：" << text.toStdString();
438	    }
439	
440	    // 清理本次产物
441	    for (const QString& dir :
442	         {QStringLiteral("/tmp"), QStringLiteral("/media")}) {
443	        QDir d(dir);
444	        for (const QString& name :
445	             d.entryList(QStringList{QStringLiteral("weaknet-dashboard-*")},
446	                         QDir::Files, QDir::Time)) {
447	            const QString path = d.filePath(name);
448	            if (QFileInfo(path).lastModified().secsTo(
449	                    QDateTime::currentDateTime()) <= 30) {
450	                QFile::remove(path);
451	            }
452	        }
453	    }
454	}
455	
456	TEST(MainWindowTest, ExportScreenshotFallsBackWhenNoUsb) {
457	    // 没有 U 盘时**必须**还能出图，且状态栏要明说落在哪。
458	    // 这是现场取证据的唯一兜底：不兜底等于「没插 U 盘就导不出」。
459	    //
