    printf("current size    = %d x %d\n", cur.width(), cur.height());

    // 逐屏型判断
    struct { const char* name; int w; int h; } screens[] = {
        {"800x480",  800, 480}, {"1024x600", 1024, 600},
        {"1024x768", 1024, 768}, {"1280x800", 1280, 800},
        {"1920x1080",1920,1080},
    };
    for (auto& s : screens) {
        bool ok = (s.w >= hint.width() && s.h >= hint.height());
        printf("  %-10s %4dx%-4d  %s\n", s.name, s.w, s.h, ok ? "可用" : "会被裁剪");
    }
    return 0;
}
EOF
